def as_number(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def first_reading(rows, zone):
    try:
        return rows[zone][0]
    except (KeyError, IndexError):
        return None


print(as_number("12.5"), first_reading({"north": []}, "north"))
